const apiBase='https://discord.com/api/v10';
const snapshotDefaultMinutes=Math.max(15,Number(process.env.SENTINEL_SNAPSHOT_INTERVAL_MINUTES??360));
const safeLimit=(v:unknown,max=500)=>Math.min(max,Math.max(1,Number(v)||50));
const safeDate=(v:unknown)=>{const d=new Date(String(v));return Number.isFinite(d.valueOf())?d.toISOString():null;};
