function rankEntities(items:any[],names:(x:any)=>string[],q:string,kind:'member'|'channel'|'role',limit=8){return items.map(value=>({value,score:entityScore(names(value),q,kind),specificity:entitySpecificity(names(value),q)})).sort((a,b)=>b.score-a.score||b.specificity-a.specificity).slice(0,limit);}
