async function aiInterpretApiQuestion(q:string,members:any[],channels:any[],roles:any[]){if(!openAIEnabled('OPENAI_SENTINEL_ENABLED'))return null;const mc=rankEntities(members,m=>[m.nick,m.user?.global_name,m.user?.username].filter(Boolean),q,'member').map(x=>({id:String(x.value.user?.id),displayName:x.value.nick??x.value.user?.global_name??x.value.user?.username,username:x.value.user?.username,score:Number(x.score.toFixed(3))}));const cc=rankEntities(channels,c=>[c.name].filter(Boolean),q,'channel').map(x=>({id:String(x.value.id),name:x.value.name,score:Number(x.score.toFixed(3))}));const rc=rankEntities(roles,r=>[r.name].filter(Boolean),q,'role').map(x=>({id:String(x.value.id),name:x.value.name,score:Number(x.score.toFixed(3))}));const out=await openAIResponse({feature:'sentinel',sensitivity:'private',model:process.env.OPENAI_SENTINEL_MODEL?.trim()||'gpt-6-luna',maxOutputTokens:240,timeoutMs:7000,instructions:`You are an intent/entity parser for a Discord audit system. Never answer the question and never invent an entity. Select only supplied IDs. Supported kinds: ${allQuestionKinds.join(', ')}. For access, accessIntent is gained, lost, current, history, or reason. Return JSON only: {"kind":"...","memberId":null,"channelId":null,"roleId":null,"accessIntent":null}.`,input:JSON.stringify({question:q,members:mc,channels:cc,roles:rc})});if(!out)return null;const j=extractJsonObject(out.text);if(!j||!allQuestionKinds.includes(j.kind))return null;return {kind:j.kind as ApiQuestionKind,member:mc.some(x=>x.id===String(j.memberId))?members.find(m=>String(m.user?.id)===String(j.memberId)):null,channel:cc.some(x=>x.id===String(j.channelId))?channels.find(c=>String(c.id)===String(j.channelId)):null,role:rc.some(x=>x.id===String(j.roleId))?roles.find(r=>String(r.id)===String(j.roleId)):null,accessIntent:['gained','lost','current','history','reason'].includes(j.accessIntent)?j.accessIntent as AccessIntent:null};}

function apiMemberId(m:any){return String(m?.user?.id??m?.id??'');}
function apiMemberName(m:any){return String(m?.nick??m?.displayName??m?.user?.global_name??m?.user?.username??m?.name??apiMemberId(m));}
function isHistorical(x:any){return Boolean(x?.historical);}
async function historicalMember(q:string){const rows=await many<any>(`SELECT target_id id,COALESCE(before_state->>'displayName',after_state->>'displayName',before_state->>'nickname',after_state->>'nickname',metadata->>'displayName',metadata->>'username') name FROM sentinel_events WHERE guild_id=$1 AND target_id IS NOT NULL AND category IN ('member','role','moderation','voice') ORDER BY occurred_at DESC LIMIT 800`,[guildId]);const found=chooseEntity(rows.filter((x:any)=>x.name),x=>[String(x.name)],q,'member');return found?{id:String(found.id),user:{id:String(found.id),username:String(found.name)},nick:String(found.name),historical:true}:null;}
async function historicalChannel(q:string){const rows=await many<any>(`SELECT COALESCE(channel_id,target_id) id,COALESCE(before_state->>'name',after_state->>'name',metadata->>'channelName',metadata->>'name') name FROM sentinel_events WHERE guild_id=$1 AND category IN ('channel','thread','voice','message','reaction') AND COALESCE(channel_id,target_id) IS NOT NULL ORDER BY occurred_at DESC LIMIT 800`,[guildId]);const found=chooseEntity(rows.filter((x:any)=>x.name),x=>[String(x.name)],q,'channel');return found?{id:String(found.id),name:String(found.name),historical:true}:null;}
async function historicalRole(q:string){const rows=await many<any>(`SELECT target_id id,COALESCE(before_state->>'name',after_state->>'name',metadata->>'roleName') name FROM sentinel_events WHERE guild_id=$1 AND target_id IS NOT NULL AND category='role' ORDER BY occurred_at DESC LIMIT 800`,[guildId]);const found=chooseEntity(rows.filter((x:any)=>x.name),x=>[String(x.name)],q,'role');return found?{id:String(found.id),name:String(found.name),historical:true}:null;}
function needs(kind:ApiQuestionKind,member:any,channel:any,role:any){const memberKinds=new Set<ApiQuestionKind>(['access','access.channels.member','member.nickname.current','member.roles.current','member.ban.current','member.timeout.current','role.current','member.roles.changed','role.gained','role.lost','member.joined','member.left','member.nickname','voice.disconnect','voice.move','voice.join','voice.leave','voice.current','voice.mute','voice.deafen','voice.mute.current','voice.deafen.current','invite.used','member.kick','member.ban','member.unban','member.timeout','activity.actor','activity.target']);const channelKinds=new Set<ApiQuestionKind>(['access','access.members','access.roles','access.permissions','channel.changed','channel.created','channel.deleted','thread.created','thread.changed','thread.deleted','voice.members.current','activity.channel']);const roleKinds=new Set<ApiQuestionKind>(['access.channels.role','access.role.current','role.current','role.members','role.created','role.changed','role.deleted','activity.role']);if(memberKinds.has(kind)&&!member)return 'member';if(channelKinds.has(kind)&&!channel)return 'channel';if(roleKinds.has(kind)&&!role)return 'role';return null;}

const P={Administrator:1n<<3n,ManageChannels:1n<<4n,ViewChannel:1n<<10n,SendMessages:1n<<11n,ManageMessages:1n<<13n,MentionEveryone:1n<<17n,Connect:1n<<20n,Speak:1n<<21n,MuteMembers:1n<<22n,DeafenMembers:1n<<23n,MoveMembers:1n<<24n,ManageRoles:1n<<28n,ManageWebhooks:1n<<29n,CreatePublicThreads:1n<<35n,CreatePrivateThreads:1n<<36n,SendMessagesInThreads:1n<<38n};
function bits(v:any){try{return BigInt(String(v??'0'));}catch{return 0n;}}
function applyOverwrite(base:bigint,ow:any){return (base&~bits(ow?.deny))|bits(ow?.allow);}
function memberPermissions(member:any,channel:any,roles:any[],ownerId:string){const mid=apiMemberId(member);if(mid===ownerId)return ~0n;const ids=new Set<string>([guildId,...(member?.roles??[]).map(String)]);let base=0n;for(const r of roles)if(ids.has(String(r.id)))base|=bits(r.permissions);if((base&P.Administrator)!==0n)return ~0n;const ows=Array.isArray(channel?.permission_overwrites)?channel.permission_overwrites:[];const everyone=ows.find((o:any)=>String(o.id)===guildId&&Number(o.type)===0);if(everyone)base=applyOverwrite(base,everyone);let deny=0n,allow=0n;for(const o of ows)if(Number(o.type)===0&&ids.has(String(o.id))&&String(o.id)!==guildId){deny|=bits(o.deny);allow|=bits(o.allow);}base=(base&~deny)|allow;const own=ows.find((o:any)=>Number(o.type)===1&&String(o.id)===mid);if(own)base=applyOverwrite(base,own);return base;}
function rolePermissions(role:any,channel:any,roles:any[]){const everyone=roles.find((r:any)=>String(r.id)===guildId);let base=bits(everyone?.permissions)|bits(role?.permissions);if((base&P.Administrator)!==0n)return ~0n;const ows=Array.isArray(channel?.permission_overwrites)?channel.permission_overwrites:[];const eo=ows.find((o:any)=>String(o.id)===guildId&&Number(o.type)===0);if(eo)base=applyOverwrite(base,eo);const ro=ows.find((o:any)=>String(o.id)===String(role?.id)&&Number(o.type)===0);if(ro)base=applyOverwrite(base,ro);return base;}
function canView(mask:bigint){return (mask&P.ViewChannel)!==0n;}
function permissionNames(mask:bigint){return Object.entries(P).filter(([,b])=>(mask&b)!==0n).map(([n])=>n.replace(/([a-z])([A-Z])/g,'$1 $2'));}
function negativeQuestion(q:string){return /\b(cannot|can't|cant|doesn't|does not|without|no access|not see|not view)\b/i.test(q);}
function visibleChannels(channels:any[]){return channels.filter(c=>Number(c.type)!==4);}
function fmtList(xs:string[],limit=30){if(!xs.length)return 'none';const head=xs.slice(0,limit);return `${head.join(', ')}${xs.length>limit?` … and ${xs.length-limit} more`:''}`;}
async function currentAccessAnswer(kind:ApiQuestionKind,q:string,member:any,channel:any,role:any,members:any[],channels:any[],roles:any[],ownerId:string){const neg=negativeQuestion(q);if(kind==='access.members'){const xs=members.filter((m:any)=>!m.user?.bot).filter((m:any)=>canView(memberPermissions(m,channel,roles,ownerId))!==neg).map(apiMemberName);return {answer:`${xs.length} member${xs.length===1?'':'s'} ${neg?'cannot':'can'} currently see #${channel.name}: ${fmtList(xs)}.`,eventId:null,confidence:'confirmed',kind};}if(kind==='access.roles'){const xs=roles.filter((r:any)=>String(r.id)!==guildId).filter((r:any)=>canView(rolePermissions(r,channel,roles))!==neg).map((r:any)=>`@${r.name}`);return {answer:`${xs.length} role${xs.length===1?'':'s'} ${neg?'cannot':'can'} currently see #${channel.name}: ${fmtList(xs)}.`,eventId:null,confidence:'confirmed',kind};}if(kind==='access.channels.member'){if(isHistorical(member))return {answer:'I can only calculate current channel visibility for a member who is currently in the server.',eventId:null,confidence:'unknown',kind};const xs=visibleChannels(channels).filter((c:any)=>canView(memberPermissions(member,c,roles,ownerId))!==neg).map((c:any)=>`#${c.name}`);return {answer:`${apiMemberName(member)} ${neg?'cannot':'can'} currently see ${xs.length} channel${xs.length===1?'':'s'}: ${fmtList(xs)}.`,eventId:null,confidence:'confirmed',kind};}if(kind==='access.channels.role'){if(isHistorical(role))return {answer:'I can only calculate current channel visibility for a role that still exists.',eventId:null,confidence:'unknown',kind};const xs=visibleChannels(channels).filter((c:any)=>canView(rolePermissions(role,c,roles))!==neg).map((c:any)=>`#${c.name}`);return {answer:`@${role.name} ${neg?'cannot':'can'} currently see ${xs.length} channel${xs.length===1?'':'s'}: ${fmtList(xs)}.`,eventId:null,confidence:'confirmed',kind};}if(kind==='access.role.current'){if(isHistorical(role)||isHistorical(channel))return {answer:'I can only calculate current access for resources that still exist.',eventId:null,confidence:'unknown',kind};const yes=canView(rolePermissions(role,channel,roles));return {answer:`@${role.name} ${yes?'can':'cannot'} currently see #${channel.name}.`,eventId:null,confidence:'confirmed',kind};}if(kind==='access.permissions'){if(member&&!isHistorical(member)){const names=permissionNames(memberPermissions(member,channel,roles,ownerId));return {answer:`${apiMemberName(member)} currently has these effective permissions in #${channel.name}: ${fmtList(names,50)}.`,eventId:null,confidence:'confirmed',kind};}if(role&&!isHistorical(role)){const names=permissionNames(rolePermissions(role,channel,roles));return {answer:`@${role.name} currently has these effective permissions in #${channel.name}: ${fmtList(names,50)}.`,eventId:null,confidence:'confirmed',kind};}return {answer:'Name a current member or role together with the channel to calculate effective permissions.',eventId:null,confidence:'unknown',kind};}return null;}

