  'sticker.created':['sticker.created','audit.sticker.create'],'sticker.changed':['sticker.updated','audit.sticker.update'],'sticker.deleted':['sticker.deleted','audit.sticker.delete'],
  'scheduled_event.created':['scheduled_event.created','audit.guild.scheduled.event.create%'],'scheduled_event.changed':['scheduled_event.updated','audit.guild.scheduled.event.update%'],'scheduled_event.deleted':['scheduled_event.deleted','audit.guild.scheduled.event.delete%'],'scheduled_event.user_added':['scheduled_event.user_added'],'scheduled_event.user_removed':['scheduled_event.user_removed'],
