  if(['access.members','access.roles','access.channels.member','access.channels.role','access.role.current','access.permissions'].includes(kind)){const a=await currentAccessAnswer(kind,q,member,channel,role,members,channels,roles,String(guild.owner_id??''));if(a)return a;}
  if(kind==='member.roles.current'){if(isHistorical(member))return {answer:'I can only show current roles for a member who is currently in the server.',eventId:null,confidence:'unknown',kind};const xs=(member.roles??[]).map((id:any)=>roles.find((r:any)=>String(r.id)===String(id))?.name).filter(Boolean);return {answer:`${memberName} currently has ${xs.length?fmtList(xs.map((x:any)=>`@${x}`),50):'no roles beyond @everyone'}.`,eventId:null,confidence:'confirmed',kind};}
