  if(kind==='role.current'){if(isHistorical(member)||isHistorical(role))return {answer:'I can only check current role membership for a member and role that still exist.',eventId:null,confidence:'unknown',kind};const yes=(member.roles??[]).map(String).includes(String(role.id));return {answer:`${memberName} ${yes?'currently has':'does not currently have'} @${role.name}.`,eventId:null,confidence:'confirmed',kind};}
