    const history=mode==='history'||kind==='member.roles.changed';return {answer:history?lines.map(x=>`• ${x}`).join('\n'):lines[0],eventId:result.rows[0].id,confidence:result.rows[0].initiator_id||result.rows[0].actor_id?'confirmed':'probable',kind,related:history?result.rows:undefined};
