  if(kind==='voice.disconnect'||kind==='voice.move'){const auditLike=kind==='voice.disconnect'?'audit.member.disconnect%':'audit.member.move%';const rows=await many<any>(`SELECT * FROM sentinel_events WHERE guild_id=$1 AND action ILIKE $2 AND target_id=$3 ORDER BY occurred_at DESC LIMIT 30`,[guildId,auditLike,mid]);for(const row of rows){if(channel){const nearby=await oneOrNone<any>(`SELECT id FROM sentinel_events WHERE guild_id=$1 AND target_id=$2 AND channel_id=$3 AND action IN ('voice.channel.left','voice.channel.joined') AND occurred_at BETWEEN $4::timestamptz-interval '15 seconds' AND $4::timestamptz+interval '15 seconds' LIMIT 1`,[guildId,mid,channel.id,row.occurred_at]);if(!nearby&&String(row.channel_id??'')!==String(channel.id))continue;}const actor=display(row.initiator_id??row.actor_id);return {answer:`${actor??'Sentinel could not verify the actor'} ${kind==='voice.disconnect'?'disconnected':'moved'} ${memberName}${channel?` ${kind==='voice.disconnect'?'from':'involving'} #${channel.name}`:''} on ${new Date(row.occurred_at).toLocaleString()}.`,eventId:row.id,confidence:actor?'confirmed':'probable',kind};}const left=await oneOrNone<any>(`SELECT * FROM sentinel_events WHERE guild_id=$1 AND target_id=$2 AND action='voice.channel.left' ${channel?'AND channel_id=$3':''} ORDER BY occurred_at DESC LIMIT 1`,channel?[guildId,mid,channel.id]:[guildId,mid]);return {answer:left?`${memberName} left voice on ${new Date(left.occurred_at).toLocaleString()}, but Sentinel cannot verify another user disconnected or moved them.`:`I don't have a matching recorded voice ${kind==='voice.disconnect'?'disconnect':'move'} for ${memberName}.`,eventId:left?.id??null,confidence:'unknown',kind};}


