let schedulerStarted=false;
function startScheduler(){if(schedulerStarted)return;schedulerStarted=true;let running=false;const tick=async()=>{if(running)return;running=true;try{const settings=await ensureSettings();const latest=await oneOrNone<any>(`SELECT created_at FROM sentinel_snapshots WHERE guild_id=$1 AND kind='scheduled' ORDER BY created_at DESC LIMIT 1`,[guildId]);const minutes=Number(settings.backup_interval_minutes??snapshotDefaultMinutes);if(!latest||Date.now()-new Date(latest.created_at).getTime()>=minutes*60000)await sentinelSnapshot('system','scheduled');if(settings.webhook_pool_enabled)await provisionWebhooks('system');if(backfillEnabled){const count=await oneOrNone<any>(`SELECT COUNT(*)::int n FROM sentinel_backfill_state WHERE guild_id=$1`,[guildId]);if(Number(count?.n??0)===0)await seedBackfill(false);}await retentionSweep(settings);}catch(e){console.warn('[sentinel] scheduler tick failed',e);}finally{running=false;}};setTimeout(()=>void tick(),15000).unref?.();setInterval(()=>void tick(),15*60000).unref?.();if(backfillEnabled){setTimeout(()=>void backfillStep(),20000).unref?.();setInterval(()=>void backfillStep(),2500).unref?.();}}
async function deleteExpiredMessagesInBatches(days:number){const batch=2500,maxBatches=8;let total=0;for(let i=0;i<maxBatches;i++){const r=await db.query(`DELETE FROM sentinel_messages WHERE ctid IN (SELECT ctid FROM sentinel_messages WHERE guild_id=$1 AND created_at<NOW()-($2::int*interval '1 day') ORDER BY created_at LIMIT $3)`,[guildId,days,batch]);total+=r.rowCount;if(r.rowCount<batch)break;}if(total)console.log(`[sentinel-retention] archived messages removed in batches count=${total}`);}
async function deleteOrphanedAssetsInBatches(){const batch=500,maxBatches=6;let total=0;for(let i=0;i<maxBatches;i++){const r=await db.query(`DELETE FROM sentinel_assets WHERE id IN (SELECT a.id FROM sentinel_assets a WHERE a.guild_id=$1 AND a.last_seen_at<NOW()-interval '7 days' AND NOT EXISTS(SELECT 1 FROM sentinel_message_assets ma WHERE ma.asset_id=a.id) AND NOT EXISTS(SELECT 1 FROM sentinel_emoji_assets ea WHERE ea.asset_id=a.id) ORDER BY a.last_seen_at LIMIT $2)`,[guildId,batch]);total+=r.rowCount;if(r.rowCount<batch)break;}if(total)console.log(`[sentinel-retention] orphaned assets removed in batches count=${total}`);}
async function retentionSweep(settings:any){const standard=Math.max(7,Number(settings.standard_retention_days??90)),messages=Math.max(7,Number(settings.message_retention_days??90)),technical=Math.max(1,Number(settings.technical_retention_days??30)),security=Math.max(30,Number(settings.security_retention_days??365));await db.query(`DELETE FROM sentinel_events WHERE guild_id=$1 AND expires_at IS NOT NULL AND expires_at<NOW()`,[guildId]);await db.query(`DELETE FROM sentinel_events WHERE guild_id=$1 AND source='discord_audit' AND occurred_at<NOW()-($2::int*interval '1 day')`,[guildId,security]);await db.query(`DELETE FROM sentinel_events WHERE guild_id=$1 AND source IN ('api','worker','redis','infrastructure') AND occurred_at<NOW()-($2::int*interval '1 day')`,[guildId,technical]);await deleteExpiredMessagesInBatches(messages);await db.query(`DELETE FROM sentinel_events WHERE guild_id=$1 AND severity NOT IN ('warning','error','critical') AND occurred_at<NOW()-($2::int*interval '1 day') AND source<>'discord_audit'`,[guildId,standard]);await deleteOrphanedAssetsInBatches();}


const CHANNEL_ACTIONS={
  view:PermissionFlagsBits.ViewChannel,
  send:PermissionFlagsBits.SendMessages,
  attach:PermissionFlagsBits.AttachFiles,
  emoji:PermissionFlagsBits.UseExternalEmojis,
  connect:PermissionFlagsBits.Connect,
  speak:PermissionFlagsBits.Speak,
  manage:PermissionFlagsBits.ManageChannels
} as const;
type ChannelAction=keyof typeof CHANNEL_ACTIONS;
function permissionBits(value:any){try{return BigInt(String(value??'0'));}catch{return 0n;}}
function computeChannelAccess(channel:any,allRoles:any[],member:any|null,roleId:string|null){
  const everybody=allRoles.find((r:any)=>String(r.id)===guildId);
  const held=member?new Set<string>(member.roles??[]):new Set(roleId?[roleId]:[]);
  let bits=permissionBits(everybody?.permissions);
  for(const role of allRoles)if(held.has(String(role.id)))bits|=permissionBits(role.permissions);
  if((bits&PermissionFlagsBits.Administrator)!==0n)return {view:true,send:true,attach:true,emoji:true,connect:true,speak:true,manage:true,admin:true};
  const ow=channel.permission_overwrites??[];
  const apply=(items:any[])=>{let deny=0n,allow=0n;for(const item of items){deny|=permissionBits(item.deny);allow|=permissionBits(item.allow);}bits=(bits&~deny)|allow;};
  apply(ow.filter((o:any)=>String(o.id)===guildId));
  apply(ow.filter((o:any)=>Number(o.type)===0&&held.has(String(o.id))&&String(o.id)!==guildId));
  if(member)apply(ow.filter((o:any)=>Number(o.type)===1&&String(o.id)===String(member.user?.id)));
  const out:any={};for(const [k,flag] of Object.entries(CHANNEL_ACTIONS))out[k]=(bits&flag)!==0n;
  if(!out.view){for(const key of ['send','attach','emoji','connect','speak','manage'])out[key]=false;}
  if(!out.connect)out.speak=false;
  return out;
}
function safePermissionRequest(input:any){
  const channelId=String(input?.channelId??''),subjectId=String(input?.subjectId??'');
  const subjectType=String(input?.subjectType??'');
  const action=String(input?.action??'').toLowerCase() as ChannelAction;
  const mode=String(input?.mode??'').toLowerCase();
  if(!/^\d{16,22}$/.test(channelId)||!/^\d{16,22}$/.test(subjectId)||!['role','member'].includes(subjectType)||!(action in CHANNEL_ACTIONS)||!['allow','deny','reset'].includes(mode))throw new Error('Invalid permission request.');
  return {channelId,subjectId,subjectType,action,mode};
}
function permissionSignature(v:any){return createHmac('sha256',process.env.INTERNAL_API_TOKEN??'sentinel').update(JSON.stringify(v)).digest('hex');}

